import{_ as a,o as t,c as n,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const u=JSON.parse('{"title":"How do people watch AI-generated videos of physical scenes?","description":"","frontmatter":{"title":"How do people watch AI-generated videos of physical scenes?","arxiv":"2602.03374","date":"2026-02-03","authors":"Danqing Shi, Lan Jiang, Katherine M. Collins, Shangzhe Wu, Ayush Tewari, Miri Zilka","categories":"cs.HC","topics":"视频真实性感知, 眼动实验, 生成内容检测","outline":[2,2]},"headers":[],"relativePath":"papers/2602.03374.md","filePath":"papers/2602.03374.md","lastUpdated":null}'),o={name:"papers/2602.03374.md"};function r(p,s,l,i,c,g){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="how-do-people-watch-ai-generated-videos-of-physical-scenes" tabindex="-1">How do people watch AI-generated videos of physical scenes? <a class="header-anchor" href="#how-do-people-watch-ai-generated-videos-of-physical-scenes" aria-label="Permalink to &quot;How do people watch AI-generated videos of physical scenes?&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2602.03374" target="_blank" rel="noreferrer">2602.03374</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-02-03</td></tr><tr><td><strong>作者</strong></td><td>Danqing Shi, Lan Jiang, Katherine M. Collins, Shangzhe Wu, Ayush Tewari, Miri Zilka</td></tr><tr><td><strong>分类</strong></td><td>cs.HC</td></tr><tr><td><strong>一句话</strong></td><td>用 40 人 × 80 段物理场景视频的眼动实验证明：改变注视行为的不是视频真假，而是&quot;是否处在检测任务中&quot;以及&quot;观众以为它是真是假&quot;。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 上只有 <strong>v2</strong>（2026-05-11 修订）提供 HTML 全文，v1 提交于 2026-02-03。本文按 v2 正文撰写，frontmatter 日期用 v1 提交日期。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频长期被当作最可靠的证据形式之一，从庭审到公共讨论都建立在&quot;看到即发生过&quot;这个默认之上。Veo 3.1 这一代模型把这个默认打碎了。已有的应对思路基本都在做检测器，或者在算生成质量指标，但都跳过了一个更基础的问题：<strong>人在看这些视频时，眼睛究竟在做什么</strong>。</p><p>这个问题不是好奇心驱动的。第一，如果人类注视行为在真视频与 AI 视频之间存在稳定差异，那这个差异就是可以喂给检测器的人类先验，也是可以拿来当生成模型评测指标的人本信号。第二，如果差异不存在，那么所有基于&quot;人能看出破绽&quot;的假设——包括很多水印与教育式对策——都要重新算账。第三，即便人分不出来，&quot;知道视频可能是假的&quot;这件事本身可能已经改变了人消费视频的方式，这是一个比检测准确率更值得担心的社会性后果。</p><p>论文刻意选了<strong>不含人脸的物理场景</strong>：燃烧、流体、光学、热力学、磁学等。这是有意避开人脸这个特例——人对面孔的敏感度远高于对一般物体，此前的 DeepFake 眼动研究结论未必能外推。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>眼动研究已经覆盖了几种生成内容。人写文本与 AI 文本的阅读差异、有无 AI 辅助时的校对行为、部分篡改图像与真图像的观看差异、真假人脸图像的感知差异都有工作。这些静态内容的结论大体一致：看 AI 内容时注意力更集中在更小、更定向的区域，因为 AI 内容在注意力意义上更可预测。</p><p>视频侧的工作几乎全部集中在换脸视频，结论是注视更多落在嘴部——因为换脸视频的说话口型最不自然。这条线有两个具体缺口。其一，当时的主流技术是 DeepFake，比现在的生成模型弱得多，&quot;能被看出来&quot;这个前提在今天未必成立。其二，只研究了人的视频，而人脸处理在视觉系统里有专用通路，结论不能直接搬到物理场景上。</p><p>作者点名的一个反差值得注意：DeepFake 换脸研究发现真视频引发<strong>更多</strong>注视与更长扫描路径，即真假之间存在显著差异。本文的结论恰好相反。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从已有知识出发，走到这个设计只需要三步。第一步是承认现代生成视频的真实度已经高到人无法可靠区分——这在社交媒体上&quot;@grok 这是真的吗&quot;这类事实核查行为的普遍化里已经有征兆。第二步是意识到，一旦真假差异不可靠，那么真正驱动行为的变量可能不是真假本身，而是<strong>主观信念</strong>与<strong>任务设定</strong>。这个区分在认知科学里是常识：期望会自上而下地塑造注意分配。第三步是设计一个能把这三个变量分开的实验：真假（刺激属性）、任务（自然观看 vs. 检测）、判断（被试认为它是真是假）。三者两两不同，必须分别统计。</p><p>论文的两段式流程正是为此：先做无检测意图的自然观看，再做显式检测，同一批被试、同类刺激，只有任务不同。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>当造假质量足够高时，&quot;真假&quot;这个客观标签不再进入视觉系统的处理回路——眼睛看不到标签，只看到像素。真正改变注视的是两件主观的事：<strong>我现在是在看故事还是在找破绽</strong>，以及<strong>我倾向于相信它是真的还是假的</strong>。前者把观看从被动理解切换成主动搜索（注视点更多、每点停留更短、扫视幅度更大）；后者决定这场搜索什么时候停下来——找不到破绽的人会一直找下去，因此把 AI 视频误判为真的人反而注视次数更多。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以论文里&quot;气球被点燃的棍子戳破&quot;那段 AI 视频为例走完整流程：</p><ol><li><strong>刺激构造</strong>。真实视频 40 段，来自两个源：Physics-IQ 数据集 20 段（固体力学、流体力学、光学、热力学、磁学五类，30 fps）与 Adobe Stock 20 段人工拍摄素材（自然、野生动物、餐饮、运动四类），全部不含可辨认人物。</li><li><strong>配对生成</strong>。对每段真视频，用文字描述保证复现同一物理现象（如&quot;一根点燃的火柴被放入一杯水中&quot;），并把关键帧一起送进 prompt 以保持风格，用 <strong>Google Veo 3.1（2025 年 10 月）</strong> 生成对应的 AI 版本。全部裁到 960×720、无生成水印、手动剪到 5 秒以匹配真实视频的长度与运动量。共 80 段。</li><li><strong>被试与设备</strong>。40 人（26 女，18–48 岁，均值 27.1），学科分布跨计算机（32.5%）、社科人文（27.5%）、工程（17.5%）、自然科学（7.5%）等，60% 从未用过视频生成工具。Gazepoint GP3 眼动仪，60 Hz，无头戴；1680×1050 显示器，坐距 60–70 cm。补贴 15 英镑，全程约 30 分钟，经剑桥大学工程系伦理委员会批准。</li><li><strong>两段任务</strong>。Part 1（8 分钟）自然观看 20 段，看完口述一句话概括；休息 5 分钟；Part 2（8 分钟）检测任务，另 20 段，判断是否 AI 生成，若是则指出哪些视觉元素让它不真实。每段视频前有 3 秒固定注视点用于标准化起始位置。<strong>关键设计</strong>：每个场景每人只看一个版本，真假交叉平衡，因此不存在同场景直接对比。</li><li><strong>数据与指标</strong>。共记录 21,379 个注视点、1,573 条扫描路径（27 条因硬件问题丢失）、800 次判断（其中 796 次有配套眼动数据）。眼动指标五项：注视次数（信息采样量）、注视时长（单点加工努力）、扫视幅度（注意跨区域转移）、扫描路径长度（探索性）、瞳孔直径（认知负荷）。检测指标为准确率，随机基线 50%。</li><li><strong>策略标注</strong>。实验后问卷收集自述策略，三位作者一致地把它们归为 <strong>logic</strong>（找异常、找违反物理规律处，如&quot;违背自然法则&quot;&quot;元素的稳定性&quot;）与 <strong>intuition</strong>（整体感觉，如&quot;人工感的纹理&quot;&quot;一切都太完美了&quot;）两类，分别 25 人与 15 人。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。全文的统计工作停留在组间显著性检验（正文以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.01</span></span></span></span> 标注），没有提出模型或推导。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>H1：任务本身会不会改变注视？</strong> 会。看真实视频时，检测任务下的平均瞳孔直径<strong>小于</strong>自然观看，作者的解读是&quot;如果视频确实是真的，找破绽比理解内容的认知负荷更低&quot;。看 AI 视频时，检测任务下注视时长更短、扫视幅度更长（均 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>），正文同时称注视次数更多——不过图 3(b) 的标注只把注视时长与扫视幅度标为显著，注视次数是否达到显著性正文未明确给出，这里如实指出。定性上，气球那段视频里自然观看的人把注意力集中在气球爆破这个最抢眼的事件和桌面残渣上，而检测任务下的人注意力更分散，明显更多落在旋转装置那处&quot;棍子从一根变成两根&quot;的生成错误区域。结论是：意识到 AI 的存在后，观看从&quot;少数位置深加工&quot;变成&quot;全局快速采样&quot;。</p><p><strong>H2：真假本身会不会改变注视？</strong> 基本不会。真假两组在两个任务里几乎没有显著差异，唯一显著项是检测任务下看 AI 视频时瞳孔更大（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>）；作者自己指出这可能是混淆——实验没有控制 AI 视频的亮度，亮度差异同样会引起瞳孔变化。但<strong>判断</strong>带来了差异：在检测任务里看 AI 视频时，最终认为它是真的那些试次，注视次数显著更多（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.01</span></span></span></span>），注视时长更短但未达显著（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.28</span></span></span></span>）。作者的解释很自然：人一直在扫视找异常，直到（错误地）认定它是真的才停下。定性证据来自三球那段视频——一个橙球快速滚动吸引注意，而网球悄悄从绿变褐才是异常；没能识别出 AI 的人注意力更多落在异常区域之外。</p><p><strong>检测准确率如何？</strong> 40 人中 36 人高于 50% 随机基线，平均 66.4%。物理类视频（S1）比专业素材类（S2）更容易识别：70.8%±24.3% 对 62.0%±23.9%。混淆矩阵这里有一处<strong>内部不一致</strong>：正文写&quot;AI 视频被误判为真的比例（18.1%）高于真视频被误判为 AI 的比例（15.5%）&quot;，而图 5 的标题写&quot;更多错误来自把真视频判成 AI&quot;。两处说法方向相反，本文以正文数字为准并明确标注该矛盾。</p><p><strong>H3：策略会不会改变注视？</strong> 会。logic 组的注视次数更多但扫视幅度更短，即在更多位置采样、但采样点彼此更靠近，呈现出更定向、更受引导的注意分布；intuition 组则相反。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：40 名被试、80 段 5 秒物理场景视频（40 段真实 + 40 段 Veo 3.1 生成）的眼动实验显示，视频真假本身几乎不改变注视行为。改变注视行为的是任务：一旦被要求检测 AI，人的眼动从&quot;少数位置深加工&quot;切换到&quot;大幅扫视、快速全局采样&quot;。同样重要的是主观判断：把 AI 视频误判为真的试次伴随显著更多的注视次数，说明搜索一直持续到人放弃为止。人类平均检测准确率仅 66.4%，物理类视频（70.8%）比专业摄制素材（62.0%）更易识别。自述用逻辑策略的人比用直觉策略的人注视更多、扫视更短，注意分布更定向。</p><p><strong>三句话版</strong>：面对足够真实的生成视频，眼动跟着信念走，不跟着事实走。检测意图本身就把观看从被动理解变成主动搜异常。人类检测准确率只有 66.4%，且不同策略对应可分辨的注视模式。</p><p><strong>一句话版</strong>：决定你怎么看一段视频的，不是它是不是假的，而是你以为它是不是假的。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>&quot;真假不影响注视&quot;这个零结果，反映的是真假确实无关，而不是实验功效不足</strong>。这是全文最重要的 claim，也是唯一一个建立在&quot;没有发现显著差异&quot;之上的 claim。</p><p>理由很具体。每个被试在每个任务里只看 20 段，其中真假各 10 段；每个场景每人只看一个版本，因此不存在被试内的同场景对比，真假差异必须跨场景估计——而场景之间的视觉差异（运动量、纹理密度、亮度）远大于真假差异，这会把噪声放大。80 段刺激中真实视频还来自两个异质来源（Physics-IQ 的实验室拍摄与 Adobe Stock 的专业摄制），风格差异本身就是一个未被建模的因素。论文既没有报效应量，也没有报功效分析或等价性检验，因此&quot;没差异&quot;与&quot;差异存在但检不出来&quot;在数据上无法区分。作者提供的间接证据是：与 DeepFake 换脸研究的显著差异形成对照，并给出&quot;那些差异可能其实来自判断而非真假&quot;的重新解释——这是合理推测，但不是对功效问题的回答。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要复现全部 80 段刺激：</p><ul><li><strong>数据</strong>：取 Physics-IQ 中 10 个场景，按论文方法用任一现成生成模型（Veo、Sora 或开源替代）产出配对的 10 段 AI 版本，全部裁到 5 秒。</li><li><strong>实现</strong>：招募 12 名被试，用消费级 60 Hz 眼动仪或经过校准的摄像头方案。关键改动：采用<strong>被试内同场景对比</strong>——每人对同一场景先后看真、假两版（顺序随机化），这样真假差异不再被场景差异淹没。</li><li><strong>测量</strong>：注视次数、平均注视时长、扫视幅度三项，加上每段的真假判断。</li><li><strong>判定</strong>：若被试内设计下真假差异仍不显著，且效应量的 95% 置信区间落在预设的等价区间内，则支持论文的零结果；若被试内设计下真假差异变显著，则说明原论文的零结果至少部分来自跨场景噪声，而不是&quot;真假无关&quot;。同时检查任务效应（自然观看 vs 检测）是否仍然稳健——这是论文最强的正结果，应当在小样本下也能复现。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给&quot;判断依赖的注视差异&quot;一个<strong>替代解释</strong>：把 AI 视频判为真的试次注视次数更多，未必是&quot;搜索持续到放弃&quot;，也可能是<strong>刺激难度的选择效应</strong>——那些视觉上更复杂、内容更丰富的 AI 视频，天然既会引发更多注视（内容多，眼睛自然要多看），又更难被识破（细节多，异常被淹没）。在这个解释下，注视次数与判断之间的关联完全由&quot;视频复杂度&quot;这个第三变量驱动，与信念无关。</p><p>构造实验来分离：对每段 AI 视频独立测量一个与被试无关的复杂度代理（例如显著性图的空间熵、光流幅值方差、物体数量），然后在回归里把复杂度作为协变量控制住，再看&quot;判断为真&quot;对注视次数的偏效应是否还在。更强的版本是做<strong>信念操纵</strong>：在观看前告诉一半被试&quot;这批视频大多数是 AI 生成的&quot;，另一半&quot;大多数是真实拍摄的&quot;，刺激完全相同。如果注视行为随着被灌输的先验改变而改变，信念驱动的解释就得到了因果支持；如果不变，那么原论文观察到的关联更可能是复杂度带来的相关，而非信念带来的因果。</p><p>一个可预测失败的场景同样值得指出：论文的刺激全部是 5 秒短片，检测任务里被试知道&quot;大约一半是 AI&quot;。真实的社交媒体消费既没有这个先验，也没有这么短的时长。在长视频、低 AI 先验的场景下，&quot;主动搜异常&quot;这个模式很可能根本不会被触发。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：论文把人类注视当作被解释的因变量，最后停在&quot;人的行为变了&quot;这个描述性结论上。但它同时产出了一个更有价值却没被使用的资产——21,379 个注视点里，检测成功者的注意力<strong>确实</strong>落在了生成错误区域上（棍子分裂处、网球变色处）。这是一份免费的、密集的、由人标出的&quot;AI 破绽在哪&quot;的空间-时间标注，论文只用它做了定性图示。</p><p><strong>新的 framing</strong>：不要把眼动当行为学结论，把它当<strong>弱监督的异常定位标签</strong>，去反向训练生成模型。具体连接的是弱监督分割与人类反馈对齐两个相邻领域：注视热力图之于生成错误，就像图像级标签之于分割掩码——噪声大但成本极低且可规模化。由此可以构造一个&quot;人眼引导的物理合理性损失&quot;：在生成模型的后训练阶段，对那些被人类注视密集覆盖且判定为 AI 的时空区域施加额外惩罚，让模型优先修复人<strong>实际会发现</strong>的破绽，而不是均匀地优化全局指标。</p><p><strong>可借鉴的工具</strong>：弱监督定位里的 CAM/多示例学习用于把稀疏注视点扩成区域标签；RLHF 里的偏好建模用于把&quot;判断为 AI&quot;与注视分布联合建模成一个奖励函数；视频异常检测里的时序定位方法用于确定破绽出现的时间窗。</p><p><strong>第一个实验</strong>：收集 200 段生成视频的注视数据（每段 10 人），训练一个轻量预测器，输入视频、输出&quot;人类会在哪些时空位置停留且会因此判定为 AI&quot;的热力图。先验证它在留出集上能否预测人类的检测成败——如果能，就说明这份信号里确实编码了可迁移的破绽结构；然后把这个预测器当作奖励模型，对一个开源视频生成器做少量 DPO 式后训练，最后用<strong>新一批人类被试</strong>测检测准确率是否下降。这个链条的价值在于它闭环：评价标准直接是&quot;人还能不能看出来&quot;，而不是任何代理指标。</p>',46)])])}const d=a(o,[["render",r]]);export{u as __pageData,d as default};
